'use strict';
/**
 * diamondOrchestratorBridge466.js — Diamond Heartbeat ↔ Orchestrator Bridge V466
 *
 * Connects V465 (DiamondHeartbeat) to V437 (ModuleOrchestrator) so that
 * heartbeat observations can be translated into orchestrator plans/intents.
 * Every sync is audited via auditLog. Fail-closed: missing heartbeat or
 * missing beat record returns a clear error and does NOT execute.
 *
 * Rules:
 *  - No new npm deps.
 *  - All identifiers end in 466.
 *  - Money steps are NEVER generated by this bridge; only non-money
 *    `diamond.observe` steps are produced, so the V402 guard path is
 *    bypassed naturally (plan.moneySteps === 0).
 *  - The agent/diamond never holds keys.
 */

const ORCH_BRIDGE_VERSION_466 = '466';

class BridgeError466 extends Error {
  constructor(msg, code) {
    super(msg);
    this.name = 'BridgeError466';
    this.code = code || 'BRIDGE_ERROR';
  }
}

/* Lazy requires — fail-closed if modules missing */
function _req466(path) { try { return require(path); } catch (_) { return null; } }

function _auditLog466() {
  const mod = _req466('./auditLog.js');
  if (!mod || !mod.defaultAuditLog) return null;
  return (type, payload) => {
    try { mod.defaultAuditLog.append(type, payload); } catch (_) {}
  };
}

function _heartbeat466(opts) {
  if (opts && opts.heartbeat) return opts.heartbeat;
  const mod = _req466('./diamondHeartbeat465.js');
  if (!mod) return null;
  // defaultDiamondHeartbeat465 returns singleton only if already created
  const hb = mod.defaultDiamondHeartbeat465 ? mod.defaultDiamondHeartbeat465() : null;
  if (!hb && opts && opts.create) {
    try {
      const engineMod = _req466('./diamondCognitionEngine462.js');
      const engine = engineMod && engineMod.defaultCognitionEngine462
        ? engineMod.defaultCognitionEngine462({})
        : null;
      return new mod.DiamondHeartbeat465({ engine465: engine });
    } catch (_) { return null; }
  }
  return hb;
}

function _orchestrator466() {
  const mod = _req466('./moduleOrchestrator437.js');
  return mod || null;
}

/**
 * Sync latest heartbeat observation into the Orchestrator as a non-money plan.
 *
 * @param {object} opts
 * @returns {object} { ok, plan, execution, version }
 */
function syncHeartbeatToOrchestrator466(opts = {}) {
  const audit = _auditLog466();
  const hb = _heartbeat466(opts);
  const orch = _orchestrator466();

  if (!orch) {
    const err = new BridgeError466('ModuleOrchestrator437 not available', 'ORCH_MISSING');
    if (audit) audit('bridge466.sync_error', { code: err.code, error: err.message });
    return { ok: false, error: err.message, code: err.code, version: ORCH_BRIDGE_VERSION_466 };
  }

  if (!hb) {
    const err = new BridgeError466('DiamondHeartbeat465 not initialized', 'HEARTBEAT_MISSING');
    if (audit) audit('bridge466.sync_error', { code: err.code, error: err.message });
    return { ok: false, error: err.message, code: err.code, version: ORCH_BRIDGE_VERSION_466 };
  }

  // Grab latest beat (fail-closed if none)
  const st = hb.status465 ? hb.status465() : null;
  const beat = st && st.lastBeat ? st.lastBeat : null;
  if (!beat) {
    const err = new BridgeError466('No heartbeat beat record available', 'BEAT_MISSING');
    if (audit) audit('bridge466.sync_error', { code: err.code, error: err.message });
    return { ok: false, error: err.message, code: err.code, version: ORCH_BRIDGE_VERSION_466 };
  }

  // Build non-money intent from observation
  const intent = {
    steps: [
      {
        id: 'observe466',
        capability: 'diamond.observe',
        args: {
          beatId: beat.at || 'unknown',
          healthScore: beat.state && beat.state.healthScore != null ? beat.state.healthScore : null,
          solvencySurplus: beat.state && beat.state.solvencySurplus != null ? beat.state.solvencySurplus : null,
          dissatisfaction: beat.state && beat.state.dissatisfaction != null ? beat.state.dissatisfaction : null,
          earlyWarningsCount: beat.trends ? beat.trends.earlyWarningsCount : 0,
          proactiveActionsCount: beat.proactive ? beat.proactive.actionsCount : 0,
          ok: beat.ok,
          at: beat.at,
        },
      },
    ],
  };

  let plan;
  try {
    plan = orch.planFromIntent437(intent);
  } catch (e) {
    const err = new BridgeError466('planFromIntent437 failed: ' + e.message, 'PLAN_REJECTED');
    if (audit) audit('bridge466.sync_error', { code: err.code, error: err.message, intent });
    return { ok: false, error: err.message, code: err.code, version: ORCH_BRIDGE_VERSION_466 };
  }

  // Safe no-op executor for observation step
  const executors = {
    'diamond.observe': (args) => ({ ok: true, observed: args }),
  };

  const ctx = {
    audit,
    executors,
    dryRun: !!opts.dryRun,
  };

  let execution;
  try {
    execution = orch.executePlan437(plan, ctx);
  } catch (e) {
    const err = new BridgeError466('executePlan437 failed: ' + e.message, 'EXEC_ERROR');
    if (audit) audit('bridge466.sync_error', { code: err.code, error: err.message, plan });
    return { ok: false, error: err.message, code: err.code, version: ORCH_BRIDGE_VERSION_466 };
  }

  if (audit) {
    audit('bridge466.sync_ok', {
      version: ORCH_BRIDGE_VERSION_466,
      planSteps: plan.stepCount,
      moneySteps: plan.moneySteps,
      completed: execution.completed,
      halted: execution.halted,
      executed: execution.executed,
    });
  }

  return {
    ok: true,
    version: ORCH_BRIDGE_VERSION_466,
    plan: { stepCount: plan.stepCount, moneySteps: plan.moneySteps, requiresGuard: plan.requiresGuard },
    execution: {
      completed: execution.completed,
      halted: execution.halted,
      haltReason: execution.haltReason,
      executed: execution.executed,
      total: execution.total,
    },
    beatSnapshot: {
      at: beat.at,
      ok: beat.ok,
      healthScore: beat.state && beat.state.healthScore,
      earlyWarningsCount: beat.trends ? beat.trends.earlyWarningsCount : 0,
    },
  };
}

/**
 * Return combined status of Heartbeat + Orchestrator.
 *
 * @param {object} opts
 * @returns {object} { ok, version, heartbeat, orchestrator, connected }
 */
function getDiamondOrchestratorStatus466(opts = {}) {
  const hb = _heartbeat466(opts);
  const orch = _orchestrator466();

  const heartbeatStatus = hb && hb.status465 ? hb.status465() : null;
  const orchVersion = orch && orch.ORCH_VERSION_437 ? orch.ORCH_VERSION_437 : null;

  return {
    ok: true,
    version: ORCH_BRIDGE_VERSION_466,
    connected: !!(hb && orch),
    heartbeat: heartbeatStatus
      ? {
          running: heartbeatStatus.running,
          intervalMs: heartbeatStatus.intervalMs,
          totalBeats: heartbeatStatus.totalBeats,
          errorCount: heartbeatStatus.errorCount,
          lastBeatAt: heartbeatStatus.lastBeat ? heartbeatStatus.lastBeat.at : null,
          lastBeatOk: heartbeatStatus.lastBeat ? heartbeatStatus.lastBeat.ok : null,
        }
      : null,
    orchestrator: orchVersion ? { version: orchVersion } : null,
  };
}

module.exports = {
  ORCH_BRIDGE_VERSION_466,
  BridgeError466,
  syncHeartbeatToOrchestrator466,
  getDiamondOrchestratorStatus466,
};
